-- Laboratório v3 (20/10/2026, pedido do dono a partir do REA do ClickMax): especialistas de criação,
-- perguntas guiadas, regra contra invenção e 3 templates por arquétipo.
--
-- Contrato: Aceleriq-Laboratorio/clickmax-rea.md (seção 6, itens 1 a 4). Função: supabase/functions/laboratorio.
--
-- 1) lab_execucoes.tipo aceita os 8 nós especialistas novos: avatar, order_bump, upsell, downsell,
--    sequencia_ofertas, secoes_pagina, sequencia_mensagens, refino_tom.
-- 2) Semente: os 3 templates oficiais novos (supabase/functions/laboratorio/modulos/templates.ts,
--    TEMPLATES_OFICIAIS_V3): "High ticket com aplicação", "Lançamento" e "Webinar", em colunas por etapa.
--
-- As perguntas guiadas e a trava do Pôr no ar (blocos rascunho_sem_fonte na saída dos nós) não mudam o
-- banco: moram na função e em lab_execucoes.saida (jsonb).
--
-- Idempotente e só amplia. Nada é apagado.

-- ─── 1) Tipos de nó das execuções ───────────────────────────────────────────
ALTER TABLE public.lab_execucoes DROP CONSTRAINT IF EXISTS lab_execucoes_tipo_check;
ALTER TABLE public.lab_execucoes
  ADD CONSTRAINT lab_execucoes_tipo_check CHECK (tipo IN ('contexto', 'midia', 'config', 'gravity', 'agente', 'copy', 'imagem', 'carrossel', 'logo', 'landing', 'anuncio', 'agente_externo', 'pesquisa', 'oferta', 'funil', 'filme', 'por_no_ar', 'avatar', 'order_bump', 'upsell', 'downsell', 'sequencia_ofertas', 'secoes_pagina', 'sequencia_mensagens', 'refino_tom'));

-- ─── 2) Semente: os 3 templates oficiais da v3 ──────────────────────────────
